const crcTable = Uint32Array.from({ length: 256 }, (_, i) => {
	let n = i;
	for (let j = 0; j < 8; j++) n = n & 1 ? 3988292384 ^ n >>> 1 : n >>> 1;
	return n >>> 0;
});

